style.css:
@-moz-document domain("pinterest.com") {
/* Background */
  body, html {
    background-color: #fff0f6 !important;
    color: #3c2a21 !important;
  }

  /* Header / Navigation */
  header, nav, [data-test-id="header-Nav"] {
    background-color: #ffcc70 !important;
    color: #3c2a21 !important;
    border-bottom: 2px solid #fcbad3 !important;
  }

  /* Search Input */
  input[type="search"], input[placeholder*="Search"] {
    background-color: #ffe3ec !important;
    color: #3c2a21 !important;
    border: 1px solid #ffc2d1 !important;
  }

  /* Pins */
  [data-test-id="pin"] {
    background-color: #fff0f6 !important;
    border: 1px solid #ffd6d6 !important;
    border-radius: 12px !important;
    transition: box-shadow 0.3s ease;
  }

  [data-test-id="pin"]:hover {
    box-shadow: 0 4px 12px rgba(255, 204, 112, 0.4) !important;
  }

  /* Buttons */
  button, [role="button"] {
    background-color: #ffc2d1 !important;
    color: #3c2a21 !important;
    border-radius: 8px !important;
    border: none !important;
    transition: background-color 0.3s ease;
  }

  button:hover, [role="button"]:hover {
    background-color: #ffafbd !important;
  }

  /* Links */
  a {
    color: #d45d79 !important;
  }

  a:hover {
    color: #ff8da1 !important;
  }

  /* Image previews (e.g. board covers or pin images) */
  img {
    border-radius: 10px !important;
  }
}
